CREATE TABLE ingestion_inputs(id uuid PRIMARY KEY, bot_id text NOT NULL, chat_id text NOT NULL, message_id text NOT NULL, project_id uuid NOT NULL, run_id uuid NOT NULL, operation_id uuid NOT NULL, report_id uuid, status text NOT NULL, message jsonb NOT NULL, callback jsonb, error text, UNIQUE(bot_id,chat_id,message_id), FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE ingestion_updates(bot_id text NOT NULL, update_id text NOT NULL, input_id uuid NOT NULL REFERENCES ingestion_inputs, PRIMARY KEY(bot_id,update_id));
CREATE TABLE ingestion_replies(id uuid PRIMARY KEY, project_id uuid NOT NULL, run_id uuid NOT NULL, operation_id uuid NOT NULL, input_id uuid REFERENCES ingestion_inputs, chat_id text NOT NULL, reply_to_message_id text, text text NOT NULL, callback_query_id text, status text NOT NULL, provider_message_id text, FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
